// === Tab: mySketch ===
let dx = 7;
let dy = 7;

let fieldCount = 30, vectorFields = [], particles = [];

class VectorField {
	constructor(x, y, radius, intensity, color) {
		this.center = createVector(x, y);
		this.squareRadius = radius * radius;
		this.intensity = intensity/(radius*sqrt(2*PI));
		this.power = -0.5/this.squareRadius;
		this.color = color;
	}

	value(x, y) {
		// Gaussian distribution
		let direction = p5.Vector.sub(createVector(x, y), this.center);
		let squareMagnitude = direction.magSq();
		direction.normalize();	
		return p5.Vector.mult(direction, this.intensity*exp(this.power*squareMagnitude));
	}
}

function closestFieldTo(x, y) {
	let position = createVector(x, y);
	let closestField, distance, minDistance = 1000000;
	for(let vectorField of vectorFields) {
		distance = p5.Vector.dist(position, vectorField.center);
		if (distance < minDistance) {
			minDistance  = distance;
			closestField = vectorField;
		}
	}

	return closestField;
}

class Particle {
	constructor(x, y, c) {
		this.position = createVector(x, y);
		this.color = c;
	}

	moveTo(x, y) {
		this.position.set(x, y);
	}
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	smooth();
	colorMode(RGB, 255, 255, 255, 1);
	background(20);
	stroke(180, 180, 220, 0.1);
	strokeWeight(random(0.8,1.1));
	colorMode(HSB);

	let hue = random(0, 360);
	for (let i = 0; i < fieldCount; i++)
		vectorFields.push(new VectorField(random(0, width), random(0, height),
																			random([-1, 1])*random(100, 400), 10000,
																			color(hue, random(20,80), random(40, 150), 0.3)));

	for (let y = 0; y < height; y += dy)
		for (let x = 0; x < width; x += dx)
			particles.push(new Particle(x, y, closestFieldTo(x, y).color));
}

function draw() {	
	//vectorFields[0].center = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

	/*
	for (let y = 0; y < height; y += dy) {
		for (let x = 0; x < width; x += dx) {
			let v = createVector(0, 0);
			for (let vectorField of vectorFields) {
				v.add(vectorField.value(x, y));
			}
			line(x, y, x + v.x, y + v.y);
		}
	*/

	var v = createVector(0, 0);
	for (let particle of particles) {
		let x1 = particle.position.x;
		let y1 = particle.position.y;

		v.set(0, 0);
		for (let vectorField of vectorFields) {
			v.add(vectorField.value(x1, y1));
		}

		let x2 = x1 + v.x*random(0.6,1.1);
		let y2 = y1 + v.y*random(0.6,1.1);

		stroke(particle.color);
		line(x1, y1, x2, y2);
		particle.moveTo(x2, y2);
	}

}

